mapper.update:
UPDATE chat_rooms
   SET last_message_at = (
       SELECT created_at
         FROM chat_messages
        WHERE chat_room_id = #{roomId}
        ORDER BY id DESC
        LIMIT 1
   )
 WHERE id = #{roomId}

mapper.select:
SELECT 
  FROM chat_messages m
 WHERE m.chat_room_id = #{roomId}
 ORDER BY m.id DESC
 LIMIT #{limit}

SELECT 
  FROM chat_messages m
 WHERE m.chat_room_id = #{roomId}
   AND m.id < #{beforeId}
 ORDER BY m.id DESC
 LIMIT #{limit}

SELECT 
  FROM chat_messages m
 WHERE m.chat_room_id = #{roomId}
   AND m.id > #{afterId}
 ORDER BY m.id ASC
 LIMIT #{limit}

