INSERT IGNORE INTO chat_message_reads (chat_message_id, member_id)
SELECT m.id, #{readerId}
  FROM chat_messages m
 WHERE m.chat_room_id = #{roomId}
   AND m.id <= #{lastMessageId}
   AND m.sender_type = #{senderType}
